const PATH_G_COUNTER1 =
  "M17899 18125 c-10 -92 1 -1759 11 -1769 27 -26 2286 -32 2302 -6 9 14 52 25 96 25 134 0 442 176 552 315 222 281 282 563 171 810 -27 62 -57 136 -66 165 -20 66 -285 335 -330 335 -18 0 -74 28 -125 63 -51 34 -127 63 -170 65 -272 10 -2440 7 -2441 -3z m2173 -273 c36 -15 113 -30 171 -34 59 -4 120 -21 137 -38 16 -16 42 -30 57 -30 37 0 216 -193 270 -291 56 -103 55 -301 -3 -431 -57 -128 -248 -298 -358 -319 -46 -9 -95 -24 -108 -34 -14 -10 -65 -25 -113 -33 -124 -21 -1896 -29 -1916 -9 -10 9 -4 42 12 73 22 41 27 210 19 611 -7 327 -2 558 12 563 66 22 1762 -5 1820 -28z";

const PATH_G_COUNTER2 =
  "M20063 15208 c-42 -4 -546 -11 -1121 -14 l-1046 -6 -4 -1138 -4 -1137 944 8 c612 5 989 -2 1071 -19 93 -20 139 -20 180 3 30 16 111 38 180 50 295 48 356 63 413 103 33 23 81 42 107 42 62 0 442 387 442 451 0 28 18 78 40 111 56 86 59 760 3 792 -21 11 -45 62 -55 113 -39 210 -484 532 -808 584 -76 13 -150 34 -164 48 -14 14 -43 24 -65 22 -21 -2 -72 -8 -113 -13z m252 -357 c61 -27 127 -43 146 -36 65 25 355 -197 441 -338 96 -157 124 -452 62 -656 -100 -330 -252 -447 -789 -606 -118 -35 -265 -40 -1037 -34 l-900 7 8 725 c5 454 -1 767 -18 837 -21 88 -19 118 7 138 20 15 384 22 1001 19 901 -6 975 -10 1079 -56z";

export function PageLoader() {
  const { progress } = useLoadingState();

  const overlayRef = useRef<HTMLDivElement | null>(null);
  const clipBRef = useRef<SVGRectElement | null>(null);
  const clipGRef = useRef<SVGRectElement | null>(null);
  const barRef = useRef<HTMLDivElement | null>(null);
  const displayRef = useRef(0);
  const targetRef = useRef(0);
  const rafRef = useRef<number>(0);
  const displayProgress = useAnimatedCounter(
    progress === 100 ? progress : 0,
    progress === 100,
    1000,
  );
  const dismissedRef = useRef(false);

  useEffect(() => {
    targetRef.current = progress;
  }, [progress]);

  useEffect(() => {
    const tick = () => {
      if (dismissedRef.current) return;
      const diff = targetRef.current - displayRef.current;
      displayRef.current += Math.abs(diff) > 0.05 ? diff * 0.04 : diff;

      const pct = displayRef.current;
      const bFrac = Math.min(pct / 100, 1);
      const gFrac = Math.max(0, (pct - 20) / 80);

      clipBRef.current?.setAttribute("height", String(bFrac * B.maxH));
      clipGRef.current?.setAttribute("height", String(gFrac * G.maxH));
      if (barRef.current) barRef.current.style.width = `${pct}%`;

      rafRef.current = requestAnimationFrame(tick);
    };

    rafRef.current = requestAnimationFrame(tick);
    return () => cancelAnimationFrame(rafRef.current);
  }, []);

  useEffect(() => {
    if (progress < 100) return;

    const delay = setTimeout(() => {
      const el = overlayRef.current;
      if (!el) return;

      el.style.opacity = "0";
      el.style.transition = "opacity 0.8s ease";

      el.addEventListener(
        "transitionend",
        () => {
          el.style.display = "none";
          dismissedRef.current = true;
        },
        { once: true },
      );
    }, DISMISS_DELAY);

    return () => clearTimeout(delay);
  }, [progress]);

  return (
    <div ref={overlayRef} className="loader-container">
      <div className="loader-inner">
        <svg
          viewBox="604 374 593 410"
          xmlns="http://www.w3.org/2000/svg"
          className="block w-[150px] md:w-[200px] h-auto"
        >
          <g transform="translate(0,1200) scale(0.04,-0.04)">
            <defs>
              <clipPath id="clipB" clipPathUnits="userSpaceOnUse">
                <rect
                  ref={clipBRef}
                  x="22700"
                  y={B.fixedY}
                  width="6225"
                  height="0"
                />
              </clipPath>
              <clipPath id="clipG" clipPathUnits="userSpaceOnUse">
                <rect
                  ref={clipGRef}
                  x="16100"
                  y={G.fixedY}
                  width="7050"
                  height="0"
                />
              </clipPath>
            </defs>

            <path fill="rgba(255,255,255,0.08)" d={PATH_B} />

            <path
              fill="rgba(255,255,255,0.08)"
              fillRule="evenodd"
              d={`${PATH_G_OUTER} ${PATH_G_COUNTER1} ${PATH_G_COUNTER2}`}
            />

            <path fill="#06b6d4" clipPath="url(#clipB)" d={PATH_B} />

            <path
              fill="#ff2d75"
              fillRule="evenodd"
              clipPath="url(#clipG)"
              d={`${PATH_G_OUTER} ${PATH_G_COUNTER1} ${PATH_G_COUNTER2}`}
            />
          </g>
        </svg>

        <div className="mt-5 h-[5px] w-[150px] md:w-[200px] rounded-full bg-white/10 overflow-hidden">
          <div
            ref={barRef}
            className="h-full w-0 rounded-full bg-(image:--primary-gradient)"
          />
        </div>
        <p className="text-center mx-auto mt-5 text-sm text-muted">
          Loading {displayProgress}%
        </p>
      </div>
    </div>
  );
}
